/** Native private reader; no embedded server address, model key or browser bridge. */
public class MainActivity extends Activity {
 private final int GREEN=Color.rgb(36,107,83), BG=Color.rgb(246,245,240), INK=Color.rgb(32,44,42);
 private LinearLayout root,content,nav,controls; private ScrollView scroll; private TextView status; private EditText search;
 private JSONArray docs=new JSONArray(); private String tab="动态",industry="全部",company="",query="";
 private final ExecutorService worker=Executors.newSingleThreadExecutor(); private volatile boolean syncing=false; private boolean reading=false;
 private final Handler foreground=new Handler(Looper.getMainLooper());
 private final Runnable refresh=new Runnable(){public void run(){if(configured()&&!syncing)sync();foreground.postDelayed(this,30000);}};
 private android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("reader",MODE_PRIVATE);loadCache();shell();if(configured())sync();else settings();}
 private boolean configured(){return !prefs.getString("server","").isEmpty();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(INK);t.setPadding(0,dp(6),0,dp(6));return t;}
 private GradientDrawable surface(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
 private TextView bold(String s,int size){TextView t=text(s,size);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextSize(13);b.setTextColor(GREEN);b.setAllCaps(false);b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));b.setBackground(surface(Color.rgb(233,240,235),12));b.setPadding(dp(12),dp(4),dp(12),dp(4));b.setOnClickListener(v->action.run());return b;}
 private String date(String value){return value.replace("T"," ").replaceAll("[+]\\d{2}:?\\d{2}$","").replace("Z","");}
 private void readerMode(boolean enabled){reading=enabled;controls.setVisibility(enabled?View.GONE:View.VISIBLE);nav.setVisibility(enabled?View.GONE:View.VISIBLE);status.setVisibility(enabled?View.GONE:View.VISIBLE);scroll.post(()->scroll.smoothScrollTo(0,0));}
 private CharSequence inline(String source){SpannableStringBuilder result=new SpannableStringBuilder();Matcher m=Pattern.compile("\\*\\*(.+?)\\*\\*|__(.+?)__").matcher(source);int end=0;while(m.find()){result.append(source.substring(end,m.start()));int start=result.length();result.append(m.group(1)!=null?m.group(1):m.group(2));result.setSpan(new StyleSpan(Typeface.BOLD),start,result.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);end=m.end();}result.append(source.substring(end));return result;}
 private void richText(LinearLayout target,String source,int size){
  StringBuilder paragraph=new StringBuilder();String[] lines=source.replace("\r","").split("\n",-1);
  for(int i=0;i<=lines.length;i++){String line=i<lines.length?lines[i]:"";String trim=line.trim();boolean heading=trim.matches("#{1,6}\\s+.+")||trim.matches("【[^】]{1,40}】")||trim.matches("[一二三四五六七八九十]+[、．].{1,35}");boolean bullet=trim.matches("(?:[-*+] |[0-9]+[.)、] ).+");boolean quote=trim.startsWith("> ");
   if(trim.isEmpty()||heading||bullet||quote){if(paragraph.length()>0){TextView t=text("",size);t.setText(inline(paragraph.toString()));t.setTextIsSelectable(true);t.setLineSpacing(dp(5),1.15f);target.addView(t);paragraph.setLength(0);}if(trim.isEmpty())continue;
    String value=heading?trim.replaceFirst("^#{1,6}\\s+",""):bullet?trim.replaceFirst("^[-*+] ","• "):quote?trim.substring(2):trim;TextView t=heading?bold(value,size+3):text("",size);if(!heading)t.setText(inline(value));t.setTextIsSelectable(true);t.setLineSpacing(dp(4),1.12f);t.setPadding(quote?dp(14):0,dp(heading?16:5),0,dp(6));if(heading)t.setTextColor(GREEN);if(quote){t.setTextColor(Color.rgb(88,105,98));t.setBackground(surface(Color.rgb(235,240,236),8));}target.addView(t);
   }else{if(paragraph.length()>0)paragraph.append("\n");paragraph.append(line);}
  }
 }

 private void shell(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(dp(16),dp(12),dp(16),dp(8));setContentView(root);
  LinearLayout head=new LinearLayout(this);TextView brand=bold("研迹",27);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));head.addView(button("设置",()->settings()));root.addView(head);
  status=text("尚未同步；可配置自己的私有服务",11);root.addView(status);
  controls=new LinearLayout(this);search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("搜索公司、行业、标题");search.setBackground(surface(Color.WHITE,14));search.setPadding(dp(14),dp(10),dp(12),dp(10));controls.addView(search,new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("同步",()->sync()));root.addView(controls);
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();render();}public void afterTextChanged(Editable e){}});
  scroll=new ScrollView(this);scroll.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  nav=new LinearLayout(this);for(String name:new String[]{"动态","行业","公司","原件","收藏"}){Button item=button(name,()->{tab=name;industry="全部";company="";render();});nav.addView(item,new LinearLayout.LayoutParams(0,dp(52),1));}root.addView(nav);render();
 }
 private void render(){if(content==null)return;readerMode(false);content.removeAllViews();for(int n=0;n<nav.getChildCount();n++){Button b=(Button)nav.getChildAt(n);boolean active=b.getText().toString().equals(tab);b.setTextColor(active?Color.WHITE:GREEN);b.setBackground(surface(active?GREEN:BG,14));}content.addView(bold(company.isEmpty()?(!industry.equals("全部")?industry:tab):company+" · 调研时间线",27));TextView caption=text(tab.equals("动态")?"研究资料 · "+docs.length()+" 篇归档":tab.equals("收藏")?"值得反复阅读的研究":tab.equals("原件")?"PDF 原件 · 本地缓存阅读":"按研究对象发现资料",12);caption.setTextColor(Color.rgb(112,126,119));content.addView(caption);
  if(tab.equals("行业")&&industry.equals("全部")){TreeSet<String> names=new TreeSet<>();for(int i=0;i<docs.length();i++){JSONArray a=docs.optJSONObject(i).optJSONArray("industries");if(a!=null)for(int j=0;j<a.length();j++)names.add(a.optString(j));}for(String n:names)content.addView(button(n,()->{industry=n;render();}));if(names.isEmpty())content.addView(text("尚无行业分类；未分析原文仍可在动态阅读。",14));return;}
  if(tab.equals("公司")&&company.isEmpty()){TreeSet<String> names=new TreeSet<>();for(int i=0;i<docs.length();i++){JSONArray a=docs.optJSONObject(i).optJSONArray("companies");if(a!=null)for(int j=0;j<a.length();j++)names.add(a.optString(j));}for(String n:names)if(query.isEmpty()||n.contains(query))content.addView(button(n,()->{company=n;render();}));if(names.isEmpty())content.addView(text("尚无已关联公司；可先在 Mac 确认公司名称。",14));return;}
  if(tab.equals("原件")){int count=0;for(int i=0;i<docs.length();i++){JSONObject d=docs.optJSONObject(i);JSONArray assets=d.optJSONArray("assets");if(assets!=null)for(int j=0;j<assets.length();j++){JSONObject a=assets.optJSONObject(j);if(a.optString("type").equals("pdf")){content.addView(button(a.optString("name"),()->downloadPdf(a)));count++;}}}if(count==0)content.addView(text("暂无已同步 PDF；请先在 Mac 导出或下载原件。",14));return;}
  if(!industry.equals("全部"))content.addView(button("← 全部行业 · "+industry,()->{industry="全部";render();}));
  if(!company.isEmpty())content.addView(button("← 公司列表",()->{company="";render();}));int count=0;
  for(int i=0;i<docs.length();i++){JSONObject d=docs.optJSONObject(i);String id=d.optString("document_id");if(tab.equals("收藏")&&!prefs.getBoolean("star:"+id,false))continue;
   if(!industry.equals("全部")&&!contains(d.optJSONArray("industries"),industry))continue;if(!company.isEmpty()&&!contains(d.optJSONArray("companies"),company))continue;
   if(!query.isEmpty()&&!(d.optString("title")+d.optString("summary")+d.optString("companies")+d.optString("industries")).contains(query))continue;
   LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setBackground(surface(Color.WHITE,18));card.setPadding(dp(13),dp(9),dp(13),dp(12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));content.addView(card,lp);
   TextView meta=text(date(d.optString("published_at"))+"  ·  "+d.optString("source_name"),11);meta.setTextColor(Color.rgb(115,128,122));card.addView(meta);TextView title=bold(d.optString("title"),19);title.setLineSpacing(dp(2),1.08f);card.addView(title);String summary=d.optString("summary");if(!summary.isEmpty()){TextView preview=text(summary.replace("**",""),14);preview.setMaxLines(3);preview.setEllipsize(TextUtils.TruncateAt.END);preview.setTextColor(Color.rgb(99,113,106));card.addView(preview);}JSONArray tags=d.optJSONArray("industries");String label=tags!=null&&tags.length()>0?tags.optString(0):"研究资料";TextView tag=text(label+(prefs.getBoolean("read:"+id,false)?"  ·  已读":"  ·  未读")+(prefs.getBoolean("star:"+id,false)?"  ★":""),11);tag.setTextColor(GREEN);card.addView(tag);
   card.setOnClickListener(v->open(d));count++;
  }if(count==0)content.addView(text(configured()?"暂无符合条件的资料。先在 Mac 同步，或调整筛选。":"请先设置私有服务地址和设备阅读凭据。",15));
 }
 private boolean contains(JSONArray values,String value){if(values==null)return false;for(int i=0;i<values.length();i++)if(values.optString(i).equals(value))return true;return false;}
 private void open(JSONObject d){if(syncing)return;String id=d.optString("document_id");prefs.edit().putBoolean("read:"+id,true).apply();
  try{File f=new File(getFilesDir(),id+".json");if(f.isFile()){JSONObject cached=new JSONObject(read(f));if(cached.optInt("revision")==d.optInt("revision")&&cached.optLong("sequence")==d.optLong("sequence")){showArticle(cached);return;}}}catch(Exception ignored){}
  syncing=true;status.setText("正在读取正文…");worker.execute(()->{try{JSONObject full=request("GET","/v1/documents/"+id,null);write(new File(getFilesDir(),id+".json"),full.toString());runOnUiThread(()->showArticle(full));}catch(Exception e){runOnUiThread(()->{status.setText("正文尚未缓存或网络不可用，联网后打开一次即可离线阅读。");render();});}finally{syncing=false;}});
 }
 private void showArticle(JSONObject d){readerMode(true);content.removeAllViews();String id=d.optString("document_id");content.addView(button("← 返回列表",()->render()));content.addView(bold(d.optString("title"),28));content.addView(text(date(d.optString("published_at"))+" · "+d.optString("source_name"),12));
  content.addView(button(prefs.getBoolean("star:"+id,false)?"★ 已收藏（点击取消）":"☆ 收藏",()->{prefs.edit().putBoolean("star:"+id,!prefs.getBoolean("star:"+id,false)).apply();showArticle(d);}));
  LinearLayout sizes=new LinearLayout(this);for(int value:new int[]{16,18,20}){sizes.addView(button(value==16?"小":value==18?"标准":"大字",()->{prefs.edit().putInt("font_size",value).apply();showArticle(d);}),new LinearLayout.LayoutParams(0,dp(44),1));}content.addView(sizes);int font=prefs.getInt("font_size",18);
  if(!d.optString("summary").isEmpty()){LinearLayout summaryBox=new LinearLayout(this);summaryBox.setOrientation(LinearLayout.VERTICAL);summaryBox.setPadding(dp(16),dp(10),dp(16),dp(14));summaryBox.setBackground(surface(Color.rgb(231,239,232),16));LinearLayout.LayoutParams summarySpace=new LinearLayout.LayoutParams(-1,-2);summarySpace.setMargins(0,dp(18),0,dp(16));content.addView(summaryBox,summarySpace);summaryBox.addView(bold("研究摘要",17));richText(summaryBox,d.optString("summary"),font-1);}content.addView(bold("归档原文",20));richText(content,d.optString("body"),font);
  JSONArray assets=d.optJSONArray("assets");if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject a=assets.optJSONObject(i);if(a.optString("type").equals("image")){ImageView view=new ImageView(this);view.setAdjustViewBounds(true);content.addView(view,new LinearLayout.LayoutParams(-1,-2));worker.execute(()->{try{File f=asset(a.optString("id"));android.graphics.BitmapFactory.Options opt=new android.graphics.BitmapFactory.Options();opt.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(f.getPath(),opt);int sample=1;while(opt.outWidth/sample>1400||opt.outHeight/sample>5000)sample*=2;opt.inJustDecodeBounds=false;opt.inSampleSize=sample;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeFile(f.getPath(),opt);runOnUiThread(()->view.setImageBitmap(bitmap));}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"原图尚未缓存或网络不可用",Toast.LENGTH_SHORT).show());}});}else content.addView(button("阅读 PDF · "+a.optString("name"),()->downloadPdf(a)));}
  String original=d.optString("source_url");if(original.startsWith("https://"))content.addView(button("打开原始来源",()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(original)))));
  status.setText("已缓存正文，可离线阅读；手机不调用模型");
 }
 private File asset(String id)throws Exception{if(!id.matches("[a-f0-9]{64}"))throw new IOException("bad asset");File file=new File(getFilesDir(),"asset-"+id);if(file.isFile())return file;
  Map<String,?> config=prefs.getAll();URL url=new URL((String)config.get("server")+"/v1/assets/"+id);HttpsURLConnection c=(HttpsURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("Authorization","Bearer "+decrypt((String)config.get("credential")));
  File tmp=new File(file.getPath()+".tmp");try{if(c.getResponseCode()!=200)throw new IOException("asset rejected");java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");int size=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){size+=n;if(size>25_000_000)throw new IOException("asset too large");out.write(buf,0,n);digest.update(buf,0,n);}out.getFD().sync();}StringBuilder actual=new StringBuilder();for(byte b:digest.digest())actual.append(String.format("%02x",b&255));if(!actual.toString().equals(id))throw new IOException("asset corrupt");if(!tmp.renameTo(file))throw new IOException("cache write failed");return file;}finally{c.disconnect();tmp.delete();}}
 private void downloadPdf(JSONObject a){if(syncing)return;syncing=true;status.setText("正在下载 PDF…");worker.execute(()->{try{File file=asset(a.optString("id"));runOnUiThread(()->pdf(file,0));}catch(Exception e){runOnUiThread(()->status.setText("PDF 下载失败，联网后重试"));}finally{syncing=false;}});}
 private void pdf(File file,int number){readerMode(true);try(android.os.ParcelFileDescriptor fd=android.os.ParcelFileDescriptor.open(file,android.os.ParcelFileDescriptor.MODE_READ_ONLY);android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(fd)){int total=renderer.getPageCount();try(android.graphics.pdf.PdfRenderer.Page page=renderer.openPage(number)){float ratio=Math.min(1.8f,Math.min(1600f/page.getWidth(),2200f/page.getHeight()));android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(Math.max(1,(int)(page.getWidth()*ratio)),Math.max(1,(int)(page.getHeight()*ratio)),android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);content.removeAllViews();content.addView(button("← 返回资料",()->render()));content.addView(text("PDF 第 "+(number+1)+" / "+total+" 页 · 本地缓存",14));LinearLayout buttons=new LinearLayout(this);if(number>0)buttons.addView(button("上一页",()->pdf(file,number-1)));if(number+1<total)buttons.addView(button("下一页",()->pdf(file,number+1)));content.addView(buttons);ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(bitmap);content.addView(image,new LinearLayout.LayoutParams(-1,-2));status.setText("PDF 已缓存，支持离线阅读");}}catch(Exception e){Toast.makeText(this,"PDF 暂无法预览",Toast.LENGTH_LONG).show();}}
 private void sync(){if(!configured()){settings();return;}if(syncing)return;syncing=true;status.setText("正在同步资料列表…");worker.execute(()->{try{
  JSONObject state=request("GET","/v1/status",null);long cursor=state.optLong("cursor",-1);if(cursor>=0&&prefs.getLong("cloud_cursor",-1)==cursor){runOnUiThread(()->status.setText("云端无新变更 · 已缓存正文可离线阅读"));return;}
  JSONArray all=new JSONArray();int offset=0;while(true){JSONObject page=request("GET","/v1/documents?limit=100&offset="+offset,null);JSONArray items=page.getJSONArray("documents");for(int i=0;i<items.length();i++)all.put(items.getJSONObject(i));offset+=items.length();if(!page.optBoolean("has_more"))break;if(offset>50000)throw new IOException("library too large");}
  write(new File(getFilesDir(),"catalog.json"),all.toString());JSONArray result=all;String stamp=new java.text.SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date());prefs.edit().putString("last_sync",stamp).putLong("cloud_cursor",cursor).apply();runOnUiThread(()->{docs=result;status.setText("已同步 "+docs.length()+" 篇 · "+stamp+"；已打开正文可离线阅读");if(!reading)render();});
 }catch(Exception e){runOnUiThread(()->status.setText("同步失败：请检查 HTTPS 地址、阅读凭据和网络；保留已有缓存。"));}finally{syncing=false;}});}
 private JSONObject request(String method,String path,JSONObject body)throws Exception{Map<String,?> config=prefs.getAll();String server=(String)config.get("server");URL url=new URL(server+path);if(!url.getProtocol().equals("https"))throw new IOException("HTTPS required");HttpsURLConnection conn=(HttpsURLConnection)url.openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(15000);conn.setReadTimeout(25000);conn.setRequestMethod(method);conn.setRequestProperty("Authorization","Bearer "+decrypt((String)config.get("credential")));try{if(body!=null){conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}if(conn.getResponseCode()!=200)throw new IOException("request rejected");try(InputStream in=conn.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>8_000_000)throw new IOException("response too large");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{conn.disconnect();}}
 private void settings(){if(syncing){Toast.makeText(this,"请等待当前同步完成后再修改连接",Toast.LENGTH_SHORT).show();return;}LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),0,dp(20),0);EditText server=new EditText(this);server.setHint("https://你的私有阅读服务");server.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);server.setText(prefs.getString("server",""));box.addView(server);EditText token=new EditText(this);token.setHint("设备阅读凭据（留空保留）");token.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(token);box.addView(text("凭据经 Android Keystore 加密保存。请勿填入 DeepSeek Key 或星球登录凭据。收藏和已读目前只存于此手机。",12));
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("连接私有阅读服务").setView(box).setNegativeButton("取消",null).setPositiveButton("保存并同步",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{try{String s=server.getText().toString().trim().replaceAll("/+$","");URI uri=new URI(s);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||uri.getPath().contains(".."))throw new Exception();String old=prefs.getString("server","");String t=token.getText().toString().trim();if(!t.isEmpty()&&t.length()<32)throw new Exception();if(t.isEmpty()&&(!old.equals(s)||prefs.getString("credential","").isEmpty()))throw new Exception();if(!old.equals(s)){docs=new JSONArray();for(File f:getFilesDir().listFiles())if(f.getName().endsWith(".json")||f.getName().startsWith("asset-"))f.delete();prefs.edit().clear().apply();}android.content.SharedPreferences.Editor edit=prefs.edit().putString("server",s);if(!t.isEmpty()){if(t.length()<32)throw new Exception();edit.putString("credential",encrypt(t));}edit.apply();dialog.dismiss();sync();}catch(Exception e){Toast.makeText(this,"请输入有效 HTTPS 根地址与至少32字符的阅读凭据",Toast.LENGTH_LONG).show();}}));dialog.show();}
 private javax.crypto.SecretKey secret()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("reader-token")){KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("reader-token",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}return (javax.crypto.SecretKey)ks.getKey("reader-token",null);}
 private String encrypt(String value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,secret());return Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);}
 private String decrypt(String value)throws Exception{String[] parts=value.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,secret(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}
 private void loadCache(){try{docs=new JSONArray(read(new File(getFilesDir(),"catalog.json")));}catch(Exception ignored){}}
 private String read(File f)throws Exception{try(InputStream in=new FileInputStream(f)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 private synchronized void write(File f,String text)throws Exception{File tmp=new File(f.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!tmp.renameTo(f))throw new IOException("cache write failed");}
 @Override public void onBackPressed(){if(reading){render();return;}if(!company.isEmpty()||!industry.equals("全部")){company="";industry="全部";render();return;}super.onBackPressed();}
 @Override protected void onResume(){super.onResume();foreground.postDelayed(refresh,30000);}
 @Override protected void onPause(){foreground.removeCallbacks(refresh);super.onPause();}
 @Override protected void onDestroy(){worker.shutdown();super.onDestroy();}
}
